// ToTop.jsx
import React, { useState, useEffect } from 'react';
import upArrow from '../../img/up-arrow.svg';
import './toTop.css';

export default function ToTop() {
    const [bottomOffset, setBottomOffset] = useState(20);

    const scrollToTop = () =>
        window.scrollTo({ top: 0, behavior: 'smooth' });

    useEffect(() => {
        const footerEl = document.getElementById('page-footer');
        if (!footerEl) return;

        const obs = new IntersectionObserver(
            ([entry]) => {
                if (entry.boundingClientRect.top < window.innerHeight) {
                    // footer is peeking in → lift the button
                    setBottomOffset(
                        window.innerHeight - entry.boundingClientRect.top + 20
                    );
                } else {
                    // footer is off‑screen → normal position
                    setBottomOffset(20);
                }
            },
            { threshold: 0 }
        );

        obs.observe(footerEl);
        return () => obs.disconnect();
    }, []);

    return (
        <aside
            className="toTop"
            onClick={scrollToTop}
            style={{ bottom: `${bottomOffset}px` }}
        >
            <div className="toTop-container">
                <img
                    src={upArrow}
                    alt="Up arrow"
                    className="toTop-img"
                />
            </div>
        </aside>
    );
}
